<?php require_once __DIR__.'/../includes/functions.php'; require_login(['admin','manager','branch_employee']); verify_csrf(); $pdo=db();
if(isset($_POST['add'])){$branch=(int)$_POST['branch_id']; if(role()!=='admin') $branch=(int)user_branch_id(); $pdo->prepare('INSERT INTO business_days (branch_id,day_name,start_time,end_time,interval_minutes,active) VALUES (?,?,?,?,?,1)')->execute([$branch,$_POST['day_name'],$_POST['start_time'],$_POST['end_time'],(int)$_POST['interval_minutes']]);flash('ok','تمت الإضافة');header('Location: business_days.php');exit;}
