$bs=$pdo->query('SELECT id,name FROM branches WHERE active=1 ORDER BY name')->fetchAll();$params=[];$cl='';if(role()!=='admin'){$cl=' WHERE d.branch_id=:b ';$params[':b']=(int)user_branch_id();}$s=$pdo->prepare('SELECT d.*,b.name branch_name FROM business_days d LEFT JOIN branches b ON b.id=d.branch_id'.$cl.' ORDER BY d.id DESC');$s->execute($params);$rows=$s->fetchAll();$title='أيام الدوام';include __DIR__.'/../includes/header.php'; ?>
